import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadAzlanData(){const e=readFileSync(resolve(__dirname,"../../azlan-shah-cup-explorer/azlan-data.js"),"utf-8");return new Function(e+"\nreturn { AZLAN_INFO, INDIA_GOLD_CAMPAIGNS, NOTABLE_LEGENDS, MEDAL_RECORD, REFERENCES };")()}describe("Sultan Azlan Shah Cup Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadAzlanData()}),describe("AZLAN_INFO metadata",()=>{it("contains correct Azlan Shah Cup metadata and founding year 1983",()=>{expect(e.AZLAN_INFO.id).toBe("azlan-shah-cup"),expect(e.AZLAN_INFO.title).toContain("Sultan Azlan Shah Cup"),expect(e.AZLAN_INFO.foundedYear).toBe("1983 CE"),expect(e.AZLAN_INFO.indiaGoldCount).toContain("5 Championship Titles")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.AZLAN_INFO.quickStats)).toBe(!0),expect(e.AZLAN_INFO.quickStats.length).toBe(6)})}),describe("INDIA_GOLD_CAMPAIGNS & NOTABLE_LEGENDS",()=>{it("contains 5 gold medal campaigns and hockey legends",()=>{expect(Array.isArray(e.INDIA_GOLD_CAMPAIGNS)).toBe(!0),expect(e.INDIA_GOLD_CAMPAIGNS.length).toBe(5),expect(Array.isArray(e.NOTABLE_LEGENDS)).toBe(!0);const t=e.NOTABLE_LEGENDS.find(e=>e.name.includes("Pillay"));expect(t).toBeDefined();const a=e.NOTABLE_LEGENDS.find(e=>e.name.includes("Sreejesh"));expect(a).toBeDefined()})}),describe("MEDAL_RECORD & REFERENCES",()=>{it("contains medal summary and reference citations",()=>{expect(Array.isArray(e.MEDAL_RECORD)).toBe(!0),expect(e.MEDAL_RECORD.length).toBe(3),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});